"use client"

import {
  type ColumnVisibilityState,
  createColumnHelper,
  useTable,
} from "@tanstack/react-table"
import {
  BuildingIcon,
  EllipsisIcon,
  EyeIcon,
  PencilIcon,
  PlusIcon,
  Trash2Icon,
} from "lucide-react"
import { useMemo } from "react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  DataTable,
  DataTableColumnHeader,
  DataTableEmpty,
  DataTableError,
  type DataTableFeatures,
  DataTableSkeleton,
  dataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import type { ResponsiveColumn } from "@/components/blocks/openlmis/data-table/responsive-columns"
import { ListToolbar } from "@/components/blocks/openlmis/list-toolbar"
import type { Approval } from "@/components/openlmis/product-editor-page/approval-form"
import {
  type ColumnVisibility,
  ColumnViewOptions,
} from "@/components/openlmis/column-view-options"

/** The columns a user may hide, and the room each needs before it shows by default. */
export const APPROVAL_HIDEABLE_COLUMNS = [
  { id: "maxPeriodsOfStock", label: "Max Periods Of Stock", hideBelow: "2xl" },
  {
    id: "emergencyOrderPoint",
    label: "Emergency Order Point",
    hideBelow: "4xl",
  },
  { id: "minPeriodsOfStock", label: "Min Periods Of Stock", hideBelow: "5xl" },
] as const satisfies readonly (ResponsiveColumn & { label: string })[]

type StockColumn = (typeof APPROVAL_HIDEABLE_COLUMNS)[number]["id"]

const byName = (a: string, b: string) => a.localeCompare(b)

/** Approvals under their facility type, both by name. */
export function groupApprovals(approvals: readonly Approval[]) {
  const groups = new Map<
    string,
    { facilityType: Approval["facilityType"]; approvals: Approval[] }
  >()
  for (const approval of approvals) {
    const group = groups.get(approval.facilityType.id)
    if (group) group.approvals.push(approval)
    else
      groups.set(approval.facilityType.id, {
        facilityType: approval.facilityType,
        approvals: [approval],
      })
  }
  return (
    [...groups.values()]
      // oxlint-disable-next-line unicorn/no-array-sort -- sorts a fresh array; toSorted needs the ES2023 lib
      .sort((a, b) => byName(a.facilityType.name, b.facilityType.name))
      .map((group) => ({
        ...group,
        // oxlint-disable-next-line unicorn/no-array-sort -- sorts a fresh array; toSorted needs the ES2023 lib
        approvals: group.approvals.sort((a, b) =>
          byName(a.program.name, b.program.name)
        ),
      }))
  )
}

type ApprovalRow =
  | { kind: "group"; id: string; facilityType: string }
  | { kind: "approval"; id: string; facilityType: string; approval: Approval }

type RowActions = {
  /** Without it, rows offer View instead of Edit and Remove. */
  canEdit: boolean
  onEdit: (approvalId: string) => void
  onRemove: (approvalId: string) => void
}

const columnHelper = createColumnHelper<DataTableFeatures, ApprovalRow>()

const number = new Intl.NumberFormat("en-US", { maximumFractionDigits: 3 })

const muted = <span className="text-muted-foreground">-</span>

function createColumns(actions: RowActions) {
  const stockColumn = (id: StockColumn, title: string) =>
    columnHelper.display({
      id,
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={title} />
      ),
      meta: { className: "w-48" },
      cell: ({ row }) => {
        if (row.original.kind === "group") return null
        const value = row.original.approval[id]
        return value == null ? (
          muted
        ) : (
          <span dir="ltr">{number.format(value)}</span>
        )
      },
    })

  return columnHelper.columns([
    columnHelper.display({
      id: "facilityType",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Facility Type" />
      ),
      cell: ({ row }) =>
        row.original.kind === "group" ? (
          <span
            className="font-medium break-words whitespace-normal"
            dir="auto"
          >
            {row.original.facilityType}
          </span>
        ) : (
          // Read out on each row, since only the group row shows it.
          <span className="sr-only">{row.original.facilityType}</span>
        ),
      meta: { className: "w-2/5 @2xl/main:w-1/5" },
    }),
    columnHelper.display({
      id: "program",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Program" />
      ),
      cell: ({ row }) =>
        row.original.kind === "approval" && (
          <span className="break-words whitespace-normal" dir="auto">
            {row.original.approval.program.name}
          </span>
        ),
    }),
    stockColumn("maxPeriodsOfStock", "Max Periods Of Stock"),
    stockColumn("emergencyOrderPoint", "Emergency Order Point"),
    stockColumn("minPeriodsOfStock", "Min Periods Of Stock"),
    columnHelper.display({
      id: "actions",
      header: () => <span className="sr-only">Actions</span>,
      meta: { className: "w-16" },
      cell: ({ row }) =>
        row.original.kind === "approval" && (
          <ApprovalActions actions={actions} approval={row.original.approval} />
        ),
    }),
  ])
}

function ApprovalActions({
  approval,
  actions,
}: {
  approval: Approval
  actions: RowActions
}) {
  return (
    <div className="flex justify-end">
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <Button
              aria-label={`Actions For ${approval.facilityType.name} In ${approval.program.name}`}
              size="icon-sm"
              variant="ghost"
            />
          }
        >
          <EllipsisIcon />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="w-auto">
          {actions.canEdit ? (
            <>
              <DropdownMenuItem onClick={() => actions.onEdit(approval.id)}>
                <PencilIcon />
                Edit
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={() => actions.onRemove(approval.id)}
                variant="destructive"
              >
                <Trash2Icon />
                Remove
              </DropdownMenuItem>
            </>
          ) : (
            <DropdownMenuItem onClick={() => actions.onEdit(approval.id)}>
              <EyeIcon />
              View
            </DropdownMenuItem>
          )}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  )
}

const NO_ROWS: ApprovalRow[] = []

const getRowId = (row: ApprovalRow) => `${row.kind}-${row.id}`

type FacilityApprovedProductsProps = RowActions & {
  /** The product's approvals; a skeleton shows until they are set. */
  approvals: readonly Approval[] | undefined
  columnVisibility: ColumnVisibilityState
  /** Replaces the table, e.g. when the approvals could not be loaded. */
  error?: string
  onRetry?: () => void
}

/** The facility types that may stock a product, each with its programs and stock levels. */
export function FacilityApprovedProducts({
  approvals,
  columnVisibility,
  error,
  onRetry,
  canEdit,
  onEdit,
  onRemove,
}: FacilityApprovedProductsProps) {
  const columns = useMemo(
    () => createColumns({ canEdit, onEdit, onRemove }),
    [canEdit, onEdit, onRemove]
  )
  const rows = useMemo(
    () =>
      approvals
        ? groupApprovals(approvals).flatMap(
            ({ facilityType, approvals: grouped }): ApprovalRow[] => [
              {
                kind: "group",
                id: facilityType.id,
                facilityType: facilityType.name,
              },
              ...grouped.map((approval) => ({
                kind: "approval" as const,
                id: approval.id,
                facilityType: facilityType.name,
                approval,
              })),
            ]
          )
        : NO_ROWS,
    [approvals]
  )
  const table = useTable({
    features: dataTableFeatures,
    columns,
    data: rows,
    getRowId,
    enableSorting: false,
    state: { columnVisibility },
  })

  if (error) {
    return (
      <DataTableError
        description="Something went wrong while loading the facility types. Try again."
        onRetry={onRetry}
        title={error}
      />
    )
  }
  if (!approvals)
    return <DataTableSkeleton footer={null} rowCount={3} table={table} />
  return (
    <DataTable
      empty={
        <DataTableEmpty
          description={
            canEdit
              ? "Add a facility type to let its facilities stock this product."
              : "No type of facility stocks this product yet."
          }
          icon={<BuildingIcon />}
          title="No Facility Types Yet"
        />
      }
      table={table}
    />
  )
}

type ApprovalsToolbarProps = {
  columnVisibility: ColumnVisibility
  onColumnVisibilityChange: (visibility: ColumnVisibility) => void
  onColumnReset?: () => void
  /** Left out when the user cannot edit approvals. */
  onAdd?: () => void
}

/** The View menu, then Add Facility Type, which takes the whole row while the tab is narrow. */
export function ApprovalsToolbar({
  columnVisibility,
  onColumnVisibilityChange,
  onColumnReset,
  onAdd,
}: ApprovalsToolbarProps) {
  return (
    <ListToolbar>
      <div className="@2xl/toolbar:ms-auto">
        <ColumnViewOptions
          columns={[...APPROVAL_HIDEABLE_COLUMNS]}
          onReset={onColumnReset}
          onVisibilityChange={onColumnVisibilityChange}
          visibility={columnVisibility}
        />
      </div>
      {onAdd && (
        <div className="w-full @2xl/toolbar:w-auto">
          <Button className="w-full" onClick={onAdd}>
            <PlusIcon data-icon="inline-start" />
            Add Facility Type
          </Button>
        </div>
      )}
    </ListToolbar>
  )
}

"use client"

import { AlertCircleIcon, Trash2Icon } from "lucide-react"
import { useRef, useState } from "react"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogMedia,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Button } from "@/components/ui/button"
import { Spinner } from "@/components/ui/spinner"
import type { Approval } from "@/components/openlmis/product-editor-page/approval-form"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"

type RemoveApprovalDialogProps = {
  /** The approval to remove; the dialog is open while it is set. */
  approvalId: string | undefined
  /** The product's approvals; one not among them shows as no longer there. */
  approvals: readonly Approval[]
  productName: string
  onConfirm: (approvalId: string) => void
  /** Locks the dialog and spins Remove while the removal runs. */
  pending?: boolean
  /** Why the removal failed; the dialog stays open to try again. */
  error?: string
  onClose: () => void
}

export function RemoveApprovalDialog({
  approvalId,
  approvals,
  productName,
  onConfirm,
  pending = false,
  error,
  onClose,
}: RemoveApprovalDialogProps) {
  const { shown, dialogProps } = useDialogTarget(approvalId, onClose)
  const cancelRef = useRef<HTMLButtonElement>(null)
  const current = approvals.find((approval) => approval.id === shown)
  // The approval as the dialog opened, so the removal does not turn it into Not Found while it closes.
  const [opened, setOpened] = useState<{
    id: string
    approval: Approval | undefined
  }>()
  if (shown !== undefined && opened?.id !== shown)
    setOpened({ id: shown, approval: current })
  const approval = opened && opened.id === shown ? opened.approval : current

  return (
    <AlertDialog {...dialogProps(pending)}>
      <AlertDialogContent initialFocus={cancelRef}>
        <AlertDialogHeader>
          <AlertDialogMedia>
            <Trash2Icon />
          </AlertDialogMedia>
          <AlertDialogTitle>
            {approval
              ? `Remove ${approval.facilityType.name} From ${approval.program.name}?`
              : "Facility Type Not Found"}
          </AlertDialogTitle>
          <AlertDialogDescription>
            {approval
              ? `Facilities of type ${approval.facilityType.name} will no longer stock ${productName} in ${approval.program.name}.`
              : "This facility type no longer stocks the product."}
          </AlertDialogDescription>
        </AlertDialogHeader>
        {error && (
          <Alert variant="destructive">
            <AlertCircleIcon />
            <AlertTitle>Could Not Remove Facility Type</AlertTitle>
            <AlertDescription>{error}</AlertDescription>
          </Alert>
        )}
        <AlertDialogFooter>
          <AlertDialogCancel disabled={pending} ref={cancelRef}>
            {approval ? "Cancel" : "Close"}
          </AlertDialogCancel>
          {approval && (
            <Button
              disabled={pending}
              focusableWhenDisabled={pending}
              onClick={() => onConfirm(approval.id)}
              variant="destructive"
            >
              {pending && <Spinner data-icon="inline-start" />}
              Remove
            </Button>
          )}
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

"use client"

import { useMemo, useState } from "react"

import { FieldGroup } from "@/components/ui/field"
import {
  FormDialog,
  FormDialogBody,
  FormDialogCancel,
  FormDialogDescription,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"

/** A product that can go into a kit. */
export type KitProduct = {
  id: string
  productCode: string
  fullProductName: string | null
  dispensingUnit?: string | null
}

/** Code and name, then the unit, so two packings of one product tell apart. */
export function kitProductLabel(product: KitProduct) {
  const name = product.fullProductName
    ? `${product.productCode} - ${product.fullProductName}`
    : product.productCode
  return product.dispensingUnit ? `${name} (${product.dispensingUnit})` : name
}

type KitProductsDialogProps = {
  open: boolean
  /** The products to pick from. */
  products: readonly KitProduct[]
  /** Left out of the choices: the kit itself and the products already in it. */
  excluded: ReadonlySet<string>
  onAdd: (products: KitProduct[]) => void
  onClose: () => void
  /** Lists only the first this many matches, with a hint to type more, as a server search would. */
  limit?: number
}

/** Pick, by code or name, the products a kit unpacks into. */
export function KitProductsDialog({
  open,
  onClose,
  ...props
}: KitProductsDialogProps) {
  const { shown, dialogProps } = useDialogTarget(open || undefined, onClose)

  return (
    <FormDialog {...dialogProps()}>
      {shown && <KitProductsForm onDone={onClose} {...props} />}
    </FormDialog>
  )
}

function KitProductsForm({
  products,
  excluded,
  onAdd,
  onDone,
  limit,
}: Omit<KitProductsDialogProps, "open" | "onClose"> & { onDone: () => void }) {
  const [typed, setTyped] = useState("")
  const matches = useMemo(() => {
    const query = typed.trim().toLowerCase()
    return products
      .filter((product) => !excluded.has(product.id))
      .map((product) => ({
        value: product.id,
        label: kitProductLabel(product),
      }))
      .filter((item) => item.label.toLowerCase().includes(query))
  }, [products, excluded, typed])
  const items = limit === undefined ? matches : matches.slice(0, limit)

  const form = useAppForm({
    defaultValues: { picked: [] as string[] },
    onSubmit: ({ value }) => {
      const picked = new Set(value.picked)
      onAdd(products.filter((product) => picked.has(product.id)))
      onDone()
    },
  })

  return (
    <FormDialogForm onSubmit={() => void form.handleSubmit()}>
      <FormDialogHeader>
        <FormDialogTitle>Add Products</FormDialogTitle>
        <FormDialogDescription>
          Search by code or name and pick the products this kit unpacks into.
          Enter their quantities in the list.
        </FormDialogDescription>
      </FormDialogHeader>
      <FormDialogBody>
        <FieldGroup>
          <form.AppField name="picked">
            {(field) => (
              <field.MultiComboboxField
                description={
                  items.length < matches.length
                    ? `The first ${items.length} of ${matches.length} matches are listed. Type more of the code or name to narrow them down.`
                    : "The kit itself and products already in it are left out."
                }
                emptyMessage="No products match."
                items={items}
                label="Products"
                onSearch={setTyped}
                placeholder="Search By Code Or Name"
                removeLabel={(label) => `Remove ${label}`}
              />
            )}
          </form.AppField>
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel />
        <form.Subscribe selector={(state) => state.values.picked.length}>
          {(count) => (
            <FormDialogSubmit disabled={count === 0}>
              {count === 0
                ? "Add Products"
                : count === 1
                  ? "Add 1 Product"
                  : `Add ${count} Products`}
            </FormDialogSubmit>
          )}
        </form.Subscribe>
      </FormDialogFooter>
    </FormDialogForm>
  )
}

import { z } from "zod"

import {
  decimalText,
  toDecimal,
  toNumberText,
} from "@/components/openlmis/number-text"
import type { NamedOption } from "@/components/openlmis/product-editor-page/program-link-form"

/** How much stock facilities of one type keep, in periods of use. */
export type ApprovalStock = {
  maxPeriodsOfStock: number
  emergencyOrderPoint: number | null
  minPeriodsOfStock: number | null
}

/** One facility type approved to stock the product in one program. */
export type Approval = ApprovalStock & {
  id: string
  facilityType: NamedOption
  program: NamedOption
}

/** What Add and Save hand back: the pair is only set when adding, since an edit keeps it. */
export type ApprovalValues = ApprovalStock & {
  facilityTypeId: string
  programId: string
}

const periods = (optional: boolean) =>
  decimalText(
    {
      required: "Enter the most periods of stock.",
      invalid: "Enter a number of 0 or more, such as 3 or 1.5.",
      tooLarge: "Enter a smaller number.",
    },
    { optional }
  )

/** Refuses a facility type and program pair already approved, other than the one being edited. */
export function approvalFormSchema(
  approved: readonly Approval[],
  editingId?: string
) {
  return z
    .object({
      facilityTypeId: z
        .string()
        .nullable()
        .refine(Boolean, "Choose a facility type."),
      programId: z.string().nullable().refine(Boolean, "Choose a program."),
      maxPeriodsOfStock: periods(false),
      emergencyOrderPoint: periods(true),
      minPeriodsOfStock: periods(true),
    })
    .superRefine((values, context) => {
      const taken = approved.some(
        (approval) =>
          approval.id !== editingId &&
          approval.facilityType.id === values.facilityTypeId &&
          approval.program.id === values.programId
      )
      if (taken) {
        context.addIssue({
          code: "custom",
          path: ["programId"],
          message:
            "This facility type already stocks the product in this program.",
        })
      }
    })
}

export type ApprovalFormValues = z.input<ReturnType<typeof approvalFormSchema>>

export const EMPTY_APPROVAL_FORM: ApprovalFormValues = {
  facilityTypeId: null,
  programId: null,
  maxPeriodsOfStock: "",
  emergencyOrderPoint: "",
  minPeriodsOfStock: "",
}

export function toApprovalFormValues(approval: Approval): ApprovalFormValues {
  return {
    facilityTypeId: approval.facilityType.id,
    programId: approval.program.id,
    maxPeriodsOfStock: toNumberText(approval.maxPeriodsOfStock),
    emergencyOrderPoint: toNumberText(approval.emergencyOrderPoint),
    minPeriodsOfStock: toNumberText(approval.minPeriodsOfStock),
  }
}

export function toApprovalValues(values: ApprovalFormValues): ApprovalValues {
  return {
    facilityTypeId: values.facilityTypeId ?? "",
    programId: values.programId ?? "",
    maxPeriodsOfStock: toDecimal(values.maxPeriodsOfStock) ?? 0,
    emergencyOrderPoint: toDecimal(values.emergencyOrderPoint),
    minPeriodsOfStock: toDecimal(values.minPeriodsOfStock),
  }
}

"use client"

import { revalidateLogic } from "@tanstack/react-form"
import { type ReactNode, useMemo } from "react"

import { FieldGroup } from "@/components/ui/field"
import type { NamedOption } from "@/components/openlmis/product-editor-page/program-link-form"
import {
  FormDialog,
  FormDialogBody,
  FormDialogCancel,
  FormDialogDescription,
  FormDialogError,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import {
  FieldSkeleton,
  SkeletonLine,
} from "@/components/openlmis/form-fields/form-fields"

import {
  type Approval,
  approvalFormSchema,
  type ApprovalValues,
  EMPTY_APPROVAL_FORM,
  toApprovalFormValues,
  toApprovalValues,
} from "@/components/openlmis/product-editor-page/approval-form"

/** `"new"` adds a facility type; an approval id edits, or views, that approval. */
export type ApprovalDialogTarget = "new" | (string & {})

type ProductApprovalDialogProps = {
  /** Opens the dialog while set. */
  target: ApprovalDialogTarget | undefined
  productName: string
  /** The product's approvals; the form shows a skeleton until they are set. */
  approvals: readonly Approval[] | undefined
  /** Every facility type; the form shows a skeleton until they are set. */
  facilityTypes: readonly NamedOption[] | undefined
  /** The programs the product is in, the only ones it can be approved for. */
  programs: readonly NamedOption[] | undefined
  /** Shows the approval without letting it change. */
  readOnly?: boolean
  /** Called with the values to save; save them, then clear `target`. */
  onSubmit: (values: ApprovalValues, existing?: Approval) => void
  /** Keeps the dialog open and spins the submit while the save runs. */
  pending?: boolean
  /** Shown above the fields, e.g. why the save failed; what was typed stays. */
  error?: ReactNode
  onClose: () => void
}

/** Let a type of facility stock the product in a program, or change how much it keeps. */
export function ProductApprovalDialog({
  target,
  pending = false,
  onClose,
  ...props
}: ProductApprovalDialogProps) {
  const { shown, dialogProps } = useDialogTarget(target, onClose)

  return (
    <FormDialog {...dialogProps(pending)}>
      {shown !== undefined && (
        <ApprovalContent
          key={shown}
          pending={pending}
          target={shown}
          {...props}
        />
      )}
    </FormDialog>
  )
}

type ContentProps = Omit<ProductApprovalDialogProps, "target" | "onClose"> & {
  target: ApprovalDialogTarget
  pending: boolean
}

function ApprovalContent({
  target,
  approvals,
  facilityTypes,
  programs,
  readOnly = false,
  ...props
}: ContentProps) {
  const adding = target === "new"
  const title = adding ? "Add Facility Type" : "Facility Type"

  if (!approvals || !facilityTypes || !programs) {
    return (
      <ApprovalSkeleton adding={adding} readOnly={readOnly} title={title} />
    )
  }
  const approval = approvals.find((item) => item.id === target)
  if (!adding && !approval) {
    return (
      <>
        <FormDialogHeader>
          <FormDialogTitle>{title}</FormDialogTitle>
          <FormDialogDescription>
            This facility type no longer stocks the product.
          </FormDialogDescription>
        </FormDialogHeader>
        <FormDialogFooter>
          <FormDialogCancel>Close</FormDialogCancel>
        </FormDialogFooter>
      </>
    )
  }
  return (
    <ApprovalForm
      approval={approval}
      approvals={approvals}
      facilityTypes={facilityTypes}
      programs={programs}
      readOnly={readOnly}
      {...props}
    />
  )
}

type ApprovalFormProps = Omit<
  ContentProps,
  "target" | "approvals" | "facilityTypes" | "programs"
> & {
  approval: Approval | undefined
  approvals: readonly Approval[]
  facilityTypes: readonly NamedOption[]
  programs: readonly NamedOption[]
  readOnly: boolean
}

const byLabel = (a: { label: string }, b: { label: string }) =>
  a.label.localeCompare(b.label)

function ApprovalForm({
  approval,
  approvals,
  facilityTypes,
  programs,
  productName,
  readOnly,
  onSubmit,
  pending,
  error,
}: ApprovalFormProps) {
  const schema = useMemo(
    () => approvalFormSchema(approvals, approval?.id),
    [approvals, approval]
  )
  const facilityTypeItems = useMemo(
    () =>
      facilityTypes
        .map((type) => ({ value: type.id, label: type.name }))
        // oxlint-disable-next-line unicorn/no-array-sort -- sorts a fresh array; toSorted needs the ES2023 lib
        .sort(byLabel),
    [facilityTypes]
  )
  const programItems = useMemo(() => {
    const items = programs.map((program) => ({
      value: program.id,
      label: program.name,
    }))
    // An approval for a program the product has since left still shows its program.
    if (approval && !items.some((item) => item.value === approval.program.id)) {
      items.push({ value: approval.program.id, label: approval.program.name })
    }
    // oxlint-disable-next-line unicorn/no-array-sort -- sorts a fresh array; toSorted needs the ES2023 lib
    return items.sort(byLabel)
  }, [programs, approval])

  const form = useAppForm({
    defaultValues: approval
      ? toApprovalFormValues(approval)
      : EMPTY_APPROVAL_FORM,
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: schema },
    onSubmit: ({ value }) => onSubmit(toApprovalValues(value), approval),
  })

  const facilityType = approval?.facilityType.name
  const title = !approval
    ? "Add Facility Type"
    : readOnly
      ? (facilityType ?? "")
      : `Edit ${facilityType}`

  return (
    <FormDialogForm onSubmit={() => void form.handleSubmit()}>
      <FormDialogHeader>
        <FormDialogTitle>{title}</FormDialogTitle>
        <FormDialogDescription>
          {approval
            ? `How much ${productName} facilities of type ${facilityType} keep for ${approval.program.name}.`
            : `Let a type of facility stock ${productName} in one of its programs.`}
        </FormDialogDescription>
      </FormDialogHeader>
      <FormDialogBody>
        <FieldGroup>
          {error && (
            <FormDialogError
              description={error}
              title="Could Not Save Facility Type"
            />
          )}
          <form.AppField name="facilityTypeId">
            {(field) => (
              <field.ComboboxField
                clearLabel="Clear Facility Type"
                description={
                  approval && !readOnly
                    ? "The facility type and program stay as they are; remove this one and add another to change them."
                    : undefined
                }
                disabled={Boolean(approval)}
                emptyMessage="No facility types match."
                items={facilityTypeItems}
                label="Facility Type"
                placeholder="Choose A Facility Type"
                required
              />
            )}
          </form.AppField>
          <form.AppField name="programId">
            {(field) => (
              <field.ComboboxField
                clearLabel="Clear Program"
                description={
                  approval ? undefined : "Only the programs the product is in."
                }
                disabled={Boolean(approval)}
                emptyMessage="Add the product to a program first."
                items={programItems}
                label="Program"
                placeholder="Choose A Program"
                required
              />
            )}
          </form.AppField>
          <form.AppField name="maxPeriodsOfStock">
            {(field) => (
              <field.DecimalField
                description="The most stock a facility keeps, in periods of use."
                disabled={readOnly}
                label="Max Periods Of Stock"
                required
              />
            )}
          </form.AppField>
          <div className="grid gap-5 @md/field-group:grid-cols-2">
            <form.AppField name="emergencyOrderPoint">
              {(field) => (
                <field.DecimalField
                  description="Stock, in periods, below which a facility orders at once."
                  disabled={readOnly}
                  label="Emergency Order Point"
                />
              )}
            </form.AppField>
            <form.AppField name="minPeriodsOfStock">
              {(field) => (
                <field.DecimalField
                  description="The least stock a facility keeps, in periods of use."
                  disabled={readOnly}
                  label="Min Periods Of Stock"
                />
              )}
            </form.AppField>
          </div>
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel disabled={pending}>
          {readOnly ? "Close" : "Cancel"}
        </FormDialogCancel>
        {!readOnly && (
          <FormDialogSubmit pending={pending}>
            {approval ? "Save" : "Add Facility Type"}
          </FormDialogSubmit>
        )}
      </FormDialogFooter>
    </FormDialogForm>
  )
}

type ApprovalSkeletonProps = {
  title: string
  adding: boolean
  readOnly: boolean
}

/** The form as it will look, so nothing moves when its choices arrive. */
function ApprovalSkeleton({ title, adding, readOnly }: ApprovalSkeletonProps) {
  return (
    <>
      <FormDialogHeader>
        <FormDialogTitle>{title}</FormDialogTitle>
        <SkeletonLine />
      </FormDialogHeader>
      <FormDialogBody>
        <div aria-busy>
          <FieldGroup>
            <FieldSkeleton label="Facility Type" required />
            <FieldSkeleton label="Program" required />
            <FieldSkeleton label="Max Periods Of Stock" required />
            <div className="grid gap-5 @md/field-group:grid-cols-2">
              <FieldSkeleton label="Emergency Order Point" />
              <FieldSkeleton label="Min Periods Of Stock" />
            </div>
          </FieldGroup>
        </div>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel>{readOnly ? "Close" : "Cancel"}</FormDialogCancel>
        {!readOnly && (
          <FormDialogSubmit disabled>
            {adding ? "Add Facility Type" : "Save"}
          </FormDialogSubmit>
        )}
      </FormDialogFooter>
    </>
  )
}

"use client"

import { PackageIcon } from "lucide-react"
import { type ReactNode, useCallback, useMemo, useState } from "react"

import { Button } from "@/components/ui/button"
import type { ColumnVisibilityState } from "@tanstack/react-table"
import {
  useColumnVisibility,
  useContainerSize,
} from "@/components/blocks/openlmis/data-table/responsive-columns"
import {
  APPROVAL_HIDEABLE_COLUMNS,
  ApprovalsToolbar,
  FacilityApprovedProducts,
} from "@/components/openlmis/product-editor-page/facility-approved-products"
import { RemoveApprovalDialog } from "@/components/openlmis/product-editor-page/remove-approval-dialog"
import type {
  Approval,
  ApprovalValues,
} from "@/components/openlmis/product-editor-page/approval-form"
import { ProductApprovalDialog } from "@/components/openlmis/product-editor-page/product-approval-dialog"
import { type Product, productName } from "@/components/openlmis/product-editor-page/product-form"
import { ProductGeneralForm } from "@/components/openlmis/product-editor-page/product-general-form"
import type {
  KitChild,
  KitChildValues,
} from "@/components/openlmis/product-editor-page/kit-form"
import { ProductKitUnpackList } from "@/components/openlmis/product-editor-page/product-kit-unpack-list"
