import {
  type NamedOption,
  type ProgramLink,
  withoutProgramLink,
  withProgramLink,
} from "@/components/openlmis/product-editor-page/program-link-form"
import {
  PROGRAM_LINK_HIDEABLE_COLUMNS,
  ProductProgramLinks,
  ProgramLinksToolbar,
} from "@/components/openlmis/product-editor-page/product-program-links"
import { RemoveProgramLinkDialog } from "@/components/openlmis/product-editor-page/remove-program-link-dialog"
import {
  Workspace,
  WorkspaceContent,
  WorkspaceDescription,
  WorkspaceFooter,
  WorkspaceHeader,
  WorkspaceHeading,
