import { z } from "zod"

import {
  toWholeNumber,
  wholeNumberText,
} from "@/components/openlmis/number-text"

/** What the product forms show and save; map your API's product onto it. */
export type Product = {
  id: string
  productCode: string
  fullProductName: string | null
  description: string | null
  dispensingUnit: string | null
  /** Set for a product sized by a size code, which then takes no dispensing unit. */
  sizeCode?: string | null
  netContent: number
  packRoundingThreshold: number
  roundToZero: boolean
}

/** A product's saved fields, trimmed, as a create or an update sends them. */
export type ProductValues = Omit<Product, "id" | "sizeCode">

/** The name a product is shown by: its full name, or its code when it has none. */
export const productName = (
  product: Pick<Product, "productCode" | "fullProductName">
) => product.fullProductName || product.productCode

const toCode = (text: string) => text.replace(/\s/g, "")

const sameCode = (a: string, b: string) =>
  toCode(a).toLowerCase() === toCode(b).toLowerCase()

const packSize = (required: string, min?: number) =>
  wholeNumberText(
    {
      required,
      invalid: "Enter a whole number, such as 1 or 12.",
      tooLarge: "Enter a number no larger than 9007199254740991.",
      tooSmall: "Enter a number of at least 1.",
    },
    { min, max: Number.MAX_SAFE_INTEGER }
  )

/** `takenCodes` are other products' codes, refused whatever their case or spacing. */
export function productFormSchema(
  takenCodes: readonly string[] = [],
  { unitRequired = true } = {}
) {
  return z.object({
    productCode: z
      .string()
      .trim()
      .min(1, "Enter a product code.")
      .refine(
        (code) => !takenCodes.some((taken) => sameCode(taken, code)),
        "Another product already has this code."
      ),
    fullProductName: z.string(),
    description: z.string(),
    dispensingUnit: unitRequired
      ? z.string().trim().min(1, "Enter a dispensing unit.")
      : z.string(),
    netContent: packSize("Enter the net content.", 1),
    packRoundingThreshold: packSize("Enter a pack rounding threshold."),
    roundToZero: z.boolean(),
  })
}

export type ProductFormValues = z.input<ReturnType<typeof productFormSchema>>

export const EMPTY_PRODUCT_FORM: ProductFormValues = {
  productCode: "",
  fullProductName: "",
  description: "",
  dispensingUnit: "",
  netContent: "",
  packRoundingThreshold: "",
  roundToZero: false,
}

export function toProductFormValues(product: Product): ProductFormValues {
  return {
    productCode: product.productCode,
    fullProductName: product.fullProductName ?? "",
    description: product.description ?? "",
    dispensingUnit: product.dispensingUnit ?? "",
    netContent: String(product.netContent),
    packRoundingThreshold: String(product.packRoundingThreshold),
    roundToZero: product.roundToZero,
  }
}

const optionalText = (text: string) => text.trim() || null

export function toProductValues(values: ProductFormValues): ProductValues {
  return {
    productCode: toCode(values.productCode),
    fullProductName: optionalText(values.fullProductName),
    description: optionalText(values.description),
    dispensingUnit: optionalText(values.dispensingUnit),
    netContent: toWholeNumber(values.netContent),
    packRoundingThreshold: toWholeNumber(values.packRoundingThreshold),
    roundToZero: values.roundToZero,
  }
}

const sameNumber = (text: string, saved: number) =>
  text.trim() !== "" && toWholeNumber(text) === saved

/** How many fields differ from the saved product. */
export function productChanges(values: ProductFormValues, saved: Product) {
  const next = toProductValues(values)
  return [
    next.productCode !== saved.productCode,
    next.fullProductName !== optionalText(saved.fullProductName ?? ""),
    next.description !== optionalText(saved.description ?? ""),
    next.dispensingUnit !== optionalText(saved.dispensingUnit ?? ""),
    !sameNumber(values.netContent, saved.netContent),
    !sameNumber(values.packRoundingThreshold, saved.packRoundingThreshold),
    next.roundToZero !== saved.roundToZero,
  ].filter(Boolean).length
}

"use client"

import { revalidateLogic, useStore } from "@tanstack/react-form"
import { type ReactNode, useEffect, useId, useMemo, useRef } from "react"

import { FieldGroup } from "@/components/ui/field"
import {
  type FormActionState,
  FormActions,
} from "@/components/openlmis/form-actions"
import { FormDialogError } from "@/components/openlmis/form-dialog/form-dialog"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import {
  ChoiceCardSkeleton,
  FieldSkeleton,
} from "@/components/openlmis/form-fields/form-fields"

import {
  type Product,
  productChanges,
  productFormSchema,
  type ProductValues,
  toProductFormValues,
  toProductValues,
} from "@/components/openlmis/product-editor-page/product-form"
import { ProductFormFields } from "@/components/openlmis/product-editor-page/product-form-fields"

type ProductGeneralFormProps = {
  /** The product; a skeleton shows until it is set. */
  product: Product | undefined
  /** Other products' codes, refused as this one's. */
  takenCodes?: readonly string[]
  /** Disables every field, e.g. without the right to edit products. */
  readOnly?: boolean
  /** Called with trimmed values; save them, then pass the saved product back. */
  onSubmit: (values: ProductValues) => void
  /** Locks Save and spins it while the save runs. */
  pending?: boolean
  /** Shown above the fields, e.g. why the save failed; what was typed stays. */
  error?: ReactNode
  /** Runs on Cancel instead of putting the form back, e.g. to leave the page. */
  onCancel?: () => void
  /** Tells the page how many changes are unsaved, e.g. to ask before leaving. */
  onChangesChange?: (changes: number) => void
  /** The form's id, for a Save placed elsewhere, e.g. in a page's `WorkspaceFooter`. */
  formId?: string
  /** Places Cancel and Save; by default they sit in a row under the form, and not at all when read only. */
  renderActions?: (actions: FormActionState) => ReactNode
}

/** A product's General tab: code, name, description and pack size. */
export function ProductGeneralForm({
  product,
  ...props
}: ProductGeneralFormProps) {
  if (!product) return <ProductGeneralFormSkeleton />
  return <GeneralForm product={product} {...props} />
}

function GeneralForm({
  product,
  takenCodes,
  readOnly = false,
  onSubmit,
  pending = false,
  error,
  onCancel,
  onChangesChange,
  renderActions,
  formId: givenFormId,
}: ProductGeneralFormProps & { product: Product }) {
  const generatedFormId = useId()
  const formId = givenFormId ?? generatedFormId
  const unitRequired = !product.sizeCode
  const schema = useMemo(
    () => productFormSchema(takenCodes, { unitRequired }),
    [takenCodes, unitRequired]
  )

  const form = useAppForm({
    defaultValues: toProductFormValues(product),
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: schema },
    onSubmit: ({ value }) => onSubmit(toProductValues(value)),
  })
  const changes = useStore(form.store, (state) =>
    productChanges(state.values, product)
  )

  // Start again only from saved values that differ, so a rebuilt but equal product keeps the draft.
  const savedKey = JSON.stringify(toProductFormValues(product))
  const lastSavedKey = useRef(savedKey)
  useEffect(() => {
    if (savedKey === lastSavedKey.current) return
    lastSavedKey.current = savedKey
    form.reset(toProductFormValues(product))
  }, [form, product, savedKey])
  useEffect(() => {
    onChangesChange?.(changes)
  }, [changes, onChangesChange])

  const actions: FormActionState = {
    formId,
    changed: changes > 0,
    pending,
    cancel: onCancel ?? (() => form.reset(toProductFormValues(product))),
  }

  return (
    <>
      <form
        className="max-w-xl"
        id={formId}
        noValidate
        onSubmit={(event) => {
          event.preventDefault()
          if (changes > 0) void form.handleSubmit()
        }}
      >
        <FieldGroup>
          {error && (
            <FormDialogError
              description={error}
              title="Could Not Save Product"
            />
          )}
          <ProductFormFields
            disabled={readOnly}
            form={form}
            sizeCode={product.sizeCode}
          />
        </FieldGroup>
      </form>
      {renderActions
        ? renderActions(actions)
        : !readOnly && (
            <div className="flex max-w-xl justify-end gap-2">
              <FormActions actions={actions} saveLabel="Save Product" />
            </div>
          )}
    </>
  )
}

export function ProductGeneralFormSkeleton() {
  return (
    <div aria-busy className="max-w-xl">
      <FieldGroup>
        <FieldSkeleton label="Product Code" required />
        <FieldSkeleton label="Name" />
        <FieldSkeleton label="Description" />
        <FieldSkeleton label="Dispensing Unit" required />
        <div className="grid gap-5 @md/field-group:grid-cols-2">
          <FieldSkeleton label="Net Content" required />
          <FieldSkeleton label="Pack Rounding Threshold" required />
        </div>
        <ChoiceCardSkeleton label="Round To Zero" />
      </FieldGroup>
    </div>
  )
}

import { z } from "zod"

import type { KitProduct } from "@/components/openlmis/product-editor-page/kit-products-dialog"
import {
  toNumberText,
  toWholeNumber,
  wholeNumberText,
} from "@/components/openlmis/number-text"

/** One product a kit unpacks into, and how many of it. */
export type KitChild = {
  product: KitProduct
  quantity: number | null
}

/** What Save hands back: each product by id, with its quantity. */
export type KitChildValues = {
  productId: string
  quantity: number
}

export const kitFormSchema = z.object({
  children: z.array(
    z.object({
      id: z.string(),
      code: z.string(),
      name: z.string(),
      quantity: wholeNumberText({
        required: "Enter a quantity.",
        invalid: "Enter a whole number, such as 0 or 12.",
        tooLarge: "Enter a number no larger than 2147483647.",
      }),
    })
  ),
})

export type KitFormValues = z.input<typeof kitFormSchema>

export type KitRow = KitFormValues["children"][number]

export const toKitRow = (product: KitProduct, quantity = ""): KitRow => ({
  id: product.id,
  code: product.productCode,
  name: product.fullProductName ?? "",
  quantity,
})

export const toKitFormValues = (
  children: readonly KitChild[]
): KitFormValues => ({
  children: children.map((child) =>
    toKitRow(child.product, toNumberText(child.quantity))
  ),
})

export const toKitChildValues = (values: KitFormValues): KitChildValues[] =>
  values.children.map((row) => ({
    productId: row.id,
    quantity: toWholeNumber(row.quantity),
  }))

/** Rows added, removed, or with a new quantity, against the saved list. */
export function kitChanges(
  rows: readonly KitRow[],
  saved: readonly KitChild[]
) {
  const savedQuantities = new Map(
    saved.map((child) => [child.product.id, child.quantity])
  )
  const kept = new Set(rows.map((row) => row.id))
  const removed = saved.filter((child) => !kept.has(child.product.id)).length
  const changed = rows.filter(
    (row) =>
      !savedQuantities.has(row.id) ||
      row.quantity.trim() === "" ||
      toWholeNumber(row.quantity) !== savedQuantities.get(row.id)
  ).length
  return removed + changed
}

